import type { Metadata } from "next";
import { db } from "@/lib/db";
import { GAME_FAMILIES } from "@/lib/games";
import { Reveal } from "@/components/marketing/Reveal";
import { Section, SectionTitle, PageHero } from "@/components/marketing/primitives";
import { FeatureCard, CtaBand, TrustBadges } from "@/components/marketing/sections";
import { AmbientField } from "@/components/marketing/AmbientField";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { GameControlPanel } from "@/components/marketing/showcase/GameControlPanel";
import { GameLogo } from "@/components/marketing/GameLogo";
import { IconCheck, IconBolt, IconShield, IconGauge, IconBackup, IconServer, IconScale } from "@/components/marketing/icons";

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Game Server Hosting — Minecraft, Rust, Valheim & more",
  description:
    "Low-latency game servers with per-game pricing. Deploy Minecraft, Rust, Valheim, Palworld, CS2 and Terraria in minutes with dedicated resources, full control, and DDoS protection.",
  alternates: { canonical: "/game-servers" },
  openGraph: {
    title: "Game Server Hosting — Nxeon",
    description: "Per-game pricing tiers with dedicated resources. Deploy a game server in minutes.",
    type: "website",
  },
};

function money(cents: number) {
  const v = cents / 100;
  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
}
function gb(mb: number) {
  return `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
}

// Per-game display name + tag. The logo/brand-colour/emoji visuals now live in
// <GameLogo> (components/marketing/GameLogo.tsx), the single source of truth.
const GAME_META: Record<string, { name: string; tag: string }> = {
  minecraft: { name: "Minecraft", tag: "Java & Bedrock" },
  valheim: { name: "Valheim", tag: "Dedicated world" },
  rust: { name: "Rust", tag: "High player counts" },
  palworld: { name: "Palworld", tag: "Co-op survival" },
  cs2: { name: "Counter-Strike 2", tag: "Competitive FPS" },
  terraria: { name: "Terraria", tag: "Sandbox worlds" },
};

// Marketing showcase of supported titles with indicative starting prices.
const SUPPORTED: { fam: string; from: string }[] = [
  { fam: "minecraft", from: "$4.99/mo" },
  { fam: "cs2", from: "$6.99/mo" },
  { fam: "valheim", from: "$9.99/mo" },
  { fam: "rust", from: "$12.99/mo" },
  { fam: "palworld", from: "$14.99/mo" },
];

const WHY = [
  { icon: <IconGauge />, title: "Low-latency APAC", body: "Hosted in our Singapore data center for tight, consistent ping across Asia-Pacific." },
  { icon: <IconBolt />, title: "One-click deploy", body: "One click provisions a fully configured server — no manual setup, live in minutes." },
  { icon: <IconBackup />, title: "Auto-updates", body: "Server versions and mods stay current automatically, so your world is always ready." },
  { icon: <IconServer />, title: "Full file & FTP access", body: "Complete control over configs, worlds, and mods with direct file and FTP access." },
  { icon: <IconScale />, title: "Instant scaling", body: "Outgrow your tier? Bump RAM, vCPU, and slots in a moment as your crew grows." },
  { icon: <IconShield />, title: "DDoS protection", body: "Always-on mitigation keeps your world online when it matters most." },
];

export default async function GameServersPage() {
  const gamePlans = await db.gamePlan.findMany({
    where: { active: true },
    orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }],
  });

  // Group active tiers by game, in the canonical family order.
  const byGame = new Map<string, typeof gamePlans>();
  for (const g of gamePlans) {
    if (!byGame.has(g.gameFamily)) byGame.set(g.gameFamily, []);
    byGame.get(g.gameFamily)!.push(g);
  }
  const games = GAME_FAMILIES.filter((f) => (byGame.get(f)?.length ?? 0) > 0);

  // "From" price anchor — cheapest active game plan, read live from the DB (the
  // same figure the pricing tiers and checkout charge); null when none exist so
  // we never invent a number.
  const fromCents = gamePlans.length ? Math.min(...gamePlans.map((p) => p.priceCents)) : null;

  return (
    <div className="relative min-h-screen overflow-hidden">
      {/* Ambient dot-field + soft aura for depth — the sitewide v5 signature. */}
      <div aria-hidden className="pointer-events-none absolute inset-0 z-0">
        <AmbientField />
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_70%_50%_at_20%_-5%,rgba(111,71,245,0.10),transparent_60%),radial-gradient(ellipse_60%_40%_at_90%_0%,rgba(59,130,246,0.08),transparent_60%)]" />
      </div>

      <div className="relative z-10">
      <PageHero
        eyebrow="Game servers"
        title="Game servers that"
        highlight="just work"
        sub="Six popular titles get dedicated per-game plans tuned to how they run — and anything else deploys on a Nxeon VPS. Pick the size that fits your crew and go live in minutes with full control and honest, all-in prices."
        primary={{ label: "Get started", href: "/register" }}
        secondary={{ label: "See pricing", href: "#pricing" }}
      >
        <div className="mt-8 flex flex-col items-center gap-5">
          {fromCents != null && (
            <div className="flex flex-wrap items-center justify-center gap-3">
              <span className="inline-flex items-center gap-2 rounded-full border border-brand-500/30 bg-brand-500/[0.08] px-4 py-1.5 text-sm">
                <span className="text-slate-400">Game servers from</span>
                <span className="font-bold text-white">{money(fromCents)}/mo</span>
                <span className="text-slate-500">·</span>
                <span className="text-slate-400">cancel anytime</span>
              </span>
            </div>
          )}
          <div className="flex justify-center">
            <TrustBadges items={["Instant deploy", "DDoS protection", "Full control panel", "Cancel anytime"]} />
          </div>
          <ReviewBadges />
        </div>
      </PageHero>

      {/* Supported games */}
      <Section tone="base" size="md">
        <SectionTitle
          eyebrow="Supported games"
          title="Deploy the titles your community plays"
          sub="One-click deploys with dedicated resources per server. Indicative starting prices — see full per-game tiers below."
        />
        <div className="mt-12 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {SUPPORTED.map((s, i) => {
            const meta = GAME_META[s.fam];
            return (
              <Reveal key={s.fam} delay={(i % 3) * 60} className="card card-hover group flex items-center gap-4">
                <GameLogo family={s.fam} size={56} />
                <div className="min-w-0">
                  <h3 className="text-base font-semibold text-white">{meta.name}</h3>
                  <p className="text-sm text-slate-400">{meta.tag}</p>
                </div>
                <span className="ml-auto shrink-0 text-right text-sm">
                  <span className="block text-slate-500">from</span>
                  <span className="font-semibold text-brand-300">{s.from}</span>
                </span>
              </Reveal>
            );
          })}
        </div>
      </Section>

      {/* Why Nxeon for game hosting */}
      <Section tone="panel" size="lg">
        <SectionTitle
          eyebrow="Why Nxeon"
          title="Built for hosting game servers"
          sub="Fast hardware near your players, full control, and the protection to keep your world online."
        />
        <div className="mt-12 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
          {WHY.map((w, i) => (
            <FeatureCard key={w.title} icon={w.icon} title={w.title} delay={(i % 3) * 60}>
              {w.body}
            </FeatureCard>
          ))}
        </div>
      </Section>

      {/* Control panel showcase */}
      <Section tone="base" size="lg">
        <div className="grid items-center gap-12 lg:grid-cols-2">
          <Reveal className="order-2 lg:order-1">
            <GameControlPanel />
          </Reveal>
          <div className="order-1 lg:order-2">
            <SectionTitle
              align="left"
              eyebrow="Full control panel"
              title="Run your world your way"
              sub="Start, stop, and restart with a click, watch players join in real time, tail the live console, and manage mods and configs — all from one panel, no SSH required."
            />
            <ul className="mt-8 space-y-4">
              {[
                "Live console, player list, and TPS at a glance",
                "One-click restart, stop, and mod management",
                "Full file & FTP access when you want to go deeper",
              ].map((t) => (
                <li key={t} className="flex items-start gap-3 text-base text-slate-300">
                  <span className="mt-1 flex-none text-emerald-400">
                    <IconCheck size={18} />
                  </span>
                  {t}
                </li>
              ))}
            </ul>
