      </Section>

      {/* Pricing per game */}
      <Section tone="base" size="lg" id="pricing">
        <SectionTitle eyebrow="Pricing" title="Pick your game, pick your size" />

        {games.length === 0 ? (
          <p className="mt-10 text-center text-slate-400">
            Game plans are being configured — check back shortly.
