import Link from "next/link";
import { Reveal } from "./Reveal";

/**
 * Marketing layout primitives (v2 redesign) — the single reuse layer every page
 * is built from, so the whole site reads as one designed thing.
 *
 *  - <Section>   full-width band with an alternating background "tone" and a
 *                consistent vertical rhythm + content rail. Replaces the ad-hoc
 *                `mx-auto max-w-6xl px-5 py-20` strings copy-pasted everywhere.
 *  - <PageHero>  the standard sub-page hero (eyebrow → title → sub → CTAs +
 *                optional visual). Replaces ~10 hand-rolled hero blocks.
 *  - <Eyebrow>   the uppercase tag above a heading.
 *  - <SectionTitle> heading + optional sub, centered or left.
 *
 * Colors and animations are the existing brand system (navy + violet/blue).
 */

type Tone = "base" | "panel" | "deep" | "light";
type Size = "sm" | "md" | "lg";

const TONE: Record<Tone, string> = {
  base: "",
  panel: "tone-panel",
  deep: "tone-deep",
  light: "tone-light",
};
const PAD: Record<Size, string> = {
  sm: "py-14 sm:py-16",
  md: "py-20 sm:py-24",
  lg: "py-24 sm:py-32",
};

/** A full-width section band. `tone` alternates the background for rhythm. */
export function Section({
  children,
  tone = "base",
  size = "md",
  id,
  className = "",
}: {
  children: React.ReactNode;
  tone?: Tone;
  size?: Size;
  id?: string;
  className?: string;
}) {
  return (
    <section id={id} className={`relative ${TONE[tone]} ${PAD[size]} ${className}`}>
      <div className="rail">{children}</div>
    </section>
  );
}

/** Uppercase eyebrow tag. `pill` gives it the bordered chip treatment. */
export function Eyebrow({ children, pill = false }: { children: React.ReactNode; pill?: boolean }) {
  return <span className={pill ? "eyebrow-pill" : "eyebrow"}>{children}</span>;
}

/** Section heading block: eyebrow + title + optional sub. */
export function SectionTitle({
  eyebrow,
  title,
  sub,
  align = "center",
  className = "",
}: {
  eyebrow?: string;
  title: React.ReactNode;
  sub?: React.ReactNode;
  align?: "center" | "left";
  className?: string;
}) {
  const alignCls = align === "center" ? "mx-auto text-center" : "text-left";
  return (
    <div className={`max-w-2xl ${alignCls} ${className}`}>
      {eyebrow && <Eyebrow>{eyebrow}</Eyebrow>}
      <h2 className="mt-3 text-3xl font-bold tracking-tight text-[var(--fg)] sm:text-4xl text-balance">{title}</h2>
      {sub && <p className="mt-4 text-lg leading-relaxed text-[var(--fg-muted)]">{sub}</p>}
    </div>
  );
}

type Cta = { label: string; href: string };

/**
 * Standard sub-page hero. Left-aligned title/sub/CTAs with an optional visual on
 * the right; falls back to centered when no visual is supplied. Renders the
 * reusable `.hero-aura` glow behind everything.
 */
export function PageHero({
  eyebrow,
  title,
  highlight,
  sub,
  primary,
  secondary,
  visual,
  logo,
  children,
}: {
  eyebrow?: string;
  title: React.ReactNode;
  /** Optional trailing fragment rendered in the brand gradient. */
  highlight?: string;
  sub?: React.ReactNode;
  primary?: Cta;
  secondary?: Cta;
  visual?: React.ReactNode;
  /** Optional brand mark (e.g. <GameLogo>) shown above the eyebrow. */
  logo?: React.ReactNode;
  children?: React.ReactNode;
}) {
  const centered = !visual;
  return (
    <section className="relative overflow-hidden">
      <div className="pointer-events-none absolute inset-0 -z-10 hero-aura" aria-hidden />
      <div className="rail py-20 sm:py-28">
        <div className={centered ? "mx-auto max-w-3xl text-center" : "grid items-center gap-12 lg:grid-cols-2"}>
          <Reveal>

