"use client";

/**
 * GameShowcaseCarousel — a premium, horizontally-scrolling showcase of the
 * supported game titles for the marketing /game-servers hero. Each title is a
 * "cover" card built from the owner's real <GameLogo> mark on its per-game brand
 * gradient, with a soft brand-colour glow. The active card expands to reveal an
 * interactive player-slot selector whose pills + "Starting at $X/mo" are driven
 * ENTIRELY by the DB game-plan tiers passed in (no invented player counts or
 * prices). Reduced-motion users get the resting frame — every transition is
 * motion-safe.
 *
 * Interaction:
 *   • Click any cover (or use the ◀ ▶ arrows) to make it the active title.
 *   • The active title shows "Players" pills, one per DB tier that defines
 *     `slots`; picking a pill swaps the shown price + RAM to that exact tier.
 *   • Mobile: the track is a CSS scroll-snap carousel (swipe horizontally).
 */

import { useRef, useState } from "react";
import Link from "next/link";
import { GameLogo, GAME_VISUAL } from "../GameLogo";
import { IconArrow, IconUsers, IconBolt } from "../icons";

/** One DB-fed price tier for a game (subset of db.gamePlan). */
export type ShowcaseTier = {
  name: string;
  ramMB: number;
  cpuCores: number;
  diskGB: number;
  slots: number | null;
  priceCents: number;
  termMonths: number;
  featured: boolean;
};

/** One game title in the showcase (built server-side from db.gamePlan). */
export type ShowcaseGame = {
  family: string;
  name: string;
  tag: string;
  /** Cheapest active tier for this title, in cents. DB-derived. */
  fromCents: number;
  tiers: ShowcaseTier[];
};

function money(cents: number) {
  const v = cents / 100;
  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
}
function gb(mb: number) {
  return `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
}
function per(term: number) {
  return term > 1 ? `/ ${term} mo` : "/mo";
}

const NEUTRAL = { from: "#334155", to: "#64748b" };

function ActivePanel({ game }: { game: ShowcaseGame }) {
  // Tiers that define player slots power the interactive selector. Fall back to
  // the raw tier order when a title has no slotted tiers (still DB-fed).
  const slotted = game.tiers.filter((t) => t.slots != null);
  const options = slotted.length ? slotted : game.tiers;
  // Default selection = the featured tier if present, else the cheapest.
  const defaultIdx = Math.max(
    0,
    options.findIndex((t) => t.featured),
  );
  const [sel, setSel] = useState(defaultIdx === -1 ? 0 : defaultIdx);
  const tier = options[sel] ?? game.tiers[0];

  if (!tier) return null;

  return (
    <div className="mt-4 border-t border-white/[0.07] pt-4">
      {slotted.length > 0 && (
        <>
          <p className="flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wide text-slate-400">
            <IconUsers size={13} /> Player slots
          </p>
          <div className="mt-2 flex flex-wrap gap-1.5" role="group" aria-label={`${game.name} player slots`}>
            {options.map((t, i) => (
              <button
                key={`${t.name}-${i}`}
                type="button"
                aria-pressed={i === sel}
                onClick={() => setSel(i)}
                className={`rounded-lg border px-2.5 py-1 text-xs font-semibold transition-colors ${
                  i === sel
                    ? "border-brand-400/60 bg-brand-500/15 text-white"
                    : "border-white/10 bg-white/[0.03] text-slate-300 hover:border-white/20 hover:text-white"
                }`}
              >
                {t.slots}
              </button>
            ))}
          </div>
        </>
      )}

      {/* Selected-tier detail — every figure below is straight from the DB tier. */}
      <div key={sel} className="mt-3 motion-safe:animate-[var(--animate-price-pop)]">
        <div className="flex items-end justify-between gap-3">
          <div>
            <p className="text-[11px] uppercase tracking-wide text-slate-500">Starting at</p>
            <p className="text-3xl font-extrabold tracking-tight text-white">
              {money(tier.priceCents)}
              <span className="ml-1 text-sm font-normal text-slate-400">{per(tier.termMonths)}</span>
            </p>
          </div>
          {tier.slots != null && (
            <span className="pb-1 text-right text-xs text-slate-400">
              up to <span className="font-semibold text-white">{tier.slots}</span> slots
            </span>
          )}
        </div>
        <ul className="mt-3 grid grid-cols-2 gap-x-3 gap-y-1.5 text-xs text-slate-300">
          <li className="flex items-center gap-1.5">
            <IconBolt size={13} className="text-brand-300" /> {gb(tier.ramMB)} RAM
          </li>
          <li className="flex items-center gap-1.5">
            <IconBolt size={13} className="text-brand-300" /> {tier.cpuCores} vCPU
          </li>
          <li className="flex items-center gap-1.5">
            <IconBolt size={13} className="text-brand-300" /> {tier.diskGB} GB NVMe
          </li>
          <li className="flex items-center gap-1.5">
            <IconBolt size={13} className="text-brand-300" /> DDoS protected
          </li>
        </ul>
      </div>

      <Link href="#pricing" className="btn-primary mt-4 w-full text-center">
        See {game.name} plans
      </Link>
    </div>
  );
}

export function GameShowcaseCarousel({ games }: { games: ShowcaseGame[] }) {
  const [active, setActive] = useState(0);
  const trackRef = useRef<HTMLDivElement>(null);
  const cardRefs = useRef<(HTMLDivElement | null)[]>([]);

  if (games.length === 0) return null;

  function select(i: number) {
    const idx = Math.max(0, Math.min(games.length - 1, i));
    setActive(idx);
    cardRefs.current[idx]?.scrollIntoView({
      behavior: "smooth",
      inline: "center",
      block: "nearest",
    });
  }

  return (
    <div className="relative">
      {/* Arrow controls — hidden on touch-first small screens (swipe instead). */}
      <div className="pointer-events-none absolute inset-y-0 left-0 right-0 z-20 hidden items-center justify-between sm:flex">
        <button
          type="button"
          aria-label="Previous game"
          onClick={() => select(active - 1)}
          disabled={active === 0}
          className="pointer-events-auto -ml-3 grid h-10 w-10 place-items-center rounded-full border border-white/10 bg-navy-900/80 text-slate-200 backdrop-blur transition hover:border-brand-500/40 hover:text-white disabled:opacity-30 lg:-ml-5"
        >
          <span className="rotate-180">
            <IconArrow size={18} />
          </span>
        </button>
        <button
          type="button"
          aria-label="Next game"
          onClick={() => select(active + 1)}
          disabled={active === games.length - 1}
          className="pointer-events-auto -mr-3 grid h-10 w-10 place-items-center rounded-full border border-white/10 bg-navy-900/80 text-slate-200 backdrop-blur transition hover:border-brand-500/40 hover:text-white disabled:opacity-30 lg:-mr-5"
        >
          <IconArrow size={18} />
        </button>
      </div>

      {/* Scroll-snap track. Each cover is a fixed-width card; the active one grows
          and reveals the interactive selector. */}
      <div
        ref={trackRef}
        className="flex snap-x snap-mandatory gap-4 overflow-x-auto scroll-smooth pb-4 pt-2 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
      >
        {/* Edge spacers so the first/last card can center on scroll. */}
        <div aria-hidden className="w-2 shrink-0 sm:w-8" />
        {games.map((g, i) => {
          const visual = GAME_VISUAL[g.family] ?? { name: g.name, glyph: "🎮", ...NEUTRAL };
          const isActive = i === active;
          return (
            <div
              key={g.family}
              ref={(el) => {
                cardRefs.current[i] = el;
              }}
              className={`group relative flex shrink-0 snap-center flex-col overflow-hidden rounded-2xl border bg-navy-900/70 p-4 backdrop-blur-md transition-all duration-300 motion-safe:duration-300 ${
                isActive
                  ? "w-[19rem] border-white/15 sm:w-[21rem]"
                  : "w-[15rem] cursor-pointer border-white/[0.06] opacity-80 hover:opacity-100 sm:w-[16rem]"
              }`}
              style={
                isActive
                  ? { boxShadow: `0 0 60px -18px ${visual.to}, 0 8px 32px -12px rgb(0 0 0 / 0.5)` }
                  : undefined
              }
              onClick={() => !isActive && select(i)}
            >
              {/* Cover art — the brand gradient with the real logo mark. */}
              <div
                className="relative flex h-40 items-center justify-center overflow-hidden rounded-xl"
                style={{
                  background: `radial-gradient(120% 90% at 50% 0%, ${visual.from}, ${visual.to})`,
                }}
              >
                <div
                  aria-hidden
                  className="absolute inset-0 opacity-40 mix-blend-overlay"
                  style={{ background: "radial-gradient(80% 60% at 50% 120%, rgba(0,0,0,0.6), transparent)" }}
                />
                <GameLogo family={g.family} size={isActive ? 84 : 68} className="relative z-10 shadow-lg" />
                {g.tiers.some((t) => t.featured) && (
                  <span className="absolute right-2 top-2 z-10 rounded-full border border-white/25 bg-black/30 px-2 py-0.5 text-[10px] font-semibold text-white backdrop-blur">
                    Popular
                  </span>
                )}
              </div>

              {/* Title + tag */}
              <div className="mt-3 flex items-start justify-between gap-2">
                <div className="min-w-0">
                  <h3 className="truncate text-base font-bold text-white">{g.name}</h3>
                  <p className="truncate text-xs text-slate-400">{g.tag}</p>
                </div>
                {!isActive && (
                  <span className="shrink-0 text-right text-xs">
                    <span className="block text-slate-500">from</span>
                    <span className="font-semibold text-brand-300">{money(g.fromCents)}</span>
                  </span>
                )}
              </div>

              {isActive ? (
                <ActivePanel game={g} />
              ) : (
                <p className="mt-2 text-xs text-slate-500">Tap to see specs & slots</p>
              )}
            </div>
          );
        })}
        <div aria-hidden className="w-2 shrink-0 sm:w-8" />
      </div>

      {/* Dot indicators */}
      <div className="mt-2 flex items-center justify-center gap-2">
        {games.map((g, i) => (
          <button
            key={g.family}
            type="button"
            aria-label={`Show ${g.name}`}
            aria-current={i === active}
            onClick={() => select(i)}
            className={`h-1.5 rounded-full transition-all ${
              i === active ? "w-6 bg-brand-400" : "w-1.5 bg-white/20 hover:bg-white/40"
            }`}
          />
        ))}
      </div>
    </div>
  );
}

